<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><style>body{font-family:DejaVu Sans;direction:rtl}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #bbb}</style><body><h1>{{$type->name_ar ?? 'إشعار تغطية'}} #{{$record->id}}</h1><table><tr><th>المريض</th><td>{{$record->patient_name}}</td><th>رقم الملف</th><td>{{$record->file_number}}</td></tr><tr><th>الهوية</th><td>{{$record->id_number}}</td><th>الجوال</th><td>{{$record->patient_mobile}}</td></tr><tr><th>جهة التغطية</th><td>{{$record->coverage_authority}}</td><th>المبلغ المطلوب</th><td>{{$record->amount_required}}</td></tr><tr><th>أيام التنويم</th><td>{{$record->hospitalization_days}}</td><th>التاريخ</th><td>{{is_numeric($record->date)?date('Y-m-d',(int)$record->date):$record->date}}</td></tr><tr><th>التفاصيل</th><td colspan="3">{{strip_tags($record->memo)}}</td></tr></table></body></html>
